import com.maan.eway.bean.EserviceCustomerDetails;
import com.maan.eway.common.req.EserviceCustomerSaveReq;
import com.maan.eway.common.res.CustomerDetailsSaveRes;
import com.maan.eway.common.service.CustomerSaveValidationService;
import com.maan.eway.common.service.EserviceCustomerDetailsService;
import com.maan.eway.error.Error;
import com.maan.eway.res.CommonRes;
import com.maan.eway.service.PrintReqService;


/**
* <h2>EserviceCustomerDetailsController</h2>
*/
@RestController
@RequestMapping("/api")
public class EserviceCustomerDetailsController {

	@Autowired
	private  EserviceCustomerDetailsService entityService;
	
	@Autowired
	private  CustomerSaveValidationService validationService;
	
	@Autowired
	private PrintReqService reqPrinter;

/*
	private static final String ENTITY_TITLE = "EserviceCustomerDetails";


 	public EserviceCustomerDetailsController (EserviceCustomerDetailsService entityService) {
		this.entityService = entityService;
	}
*/

	@PostMapping("/savecustomerdetails")
	public ResponseEntity<CommonRes> saveCustomerDetails(@RequestBody  EserviceCustomerSaveReq req) {
		reqPrinter.reqPrint(req);
		CommonRes data = new CommonRes();
		List<Error> validation = validationService.validateCustomerDetails(req);
		//// validation
		if (validation != null && validation.size() != 0) {
			data.setCommonResponse(null);
			data.setIsError(true);
			data.setErrorMessage(validation);
			data.setMessage("Failed");
			return new ResponseEntity<CommonRes>(data, HttpStatus.OK);

		} else {
			/////// save
			CustomerDetailsSaveRes res = entityService.saveCustomerDetails(req);
			data.setCommonResponse(res);
			data.setIsError(false);
			data.setErrorMessage(Collections.emptyList());
			data.setMessage("Success");
			if (res != null) {
				return new ResponseEntity<CommonRes>(data, HttpStatus.CREATED);
			} else {
				return new ResponseEntity<>(null, HttpStatus.BAD_REQUEST);
			}
		}
    }


}
